import os
import zipfile
import tempfile
import shutil
from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework.parsers import MultiPartParser
from rest_framework import status
from django.conf import settings


EXTRACT_BASE = getattr(settings, 'UPLOAD_EXTRACT_DIR', '/var/app/uploads')


class DocumentUploadView(APIView):
    """API endpoint for uploading ZIP archives containing documents.
    Extracts contents for downstream processing pipeline.
    """
    parser_classes = [MultiPartParser]

    def post(self, request, format=None):
        uploaded_file = request.FILES.get('archive')
        if not uploaded_file:
            return Response(
                {'error': 'No archive file provided'},
                status=status.HTTP_400_BAD_REQUEST
            )

        if not uploaded_file.name.endswith('.zip'):
            return Response(
                {'error': 'Only ZIP archives are accepted'},
                status=status.HTTP_400_BAD_REQUEST
            )

        # Size check - max 50MB
        if uploaded_file.size > 50 * 1024 * 1024:
            return Response(
                {'error': 'Archive exceeds maximum size of 50MB'},
                status=status.HTTP_413_REQUEST_ENTITY_TOO_LARGE
            )

        tmp_dir = tempfile.mkdtemp(prefix='doc_upload_')
        try:
            # Save uploaded file to temp location
            zip_path = os.path.join(tmp_dir, 'upload.zip')
            with open(zip_path, 'wb') as f:
                for chunk in uploaded_file.chunks():
                    f.write(chunk)

            # Validate it's a proper zip
            if not zipfile.is_zipfile(zip_path):
                return Response(
                    {'error': 'Invalid ZIP archive'},
                    status=status.HTTP_400_BAD_REQUEST
                )

            # Extract archive contents
            extracted_files = self._extract_archive(zip_path)

            return Response({
                'message': 'Archive processed successfully',
                'files_extracted': len(extracted_files),
                'filenames': extracted_files
            }, status=status.HTTP_201_CREATED)

        except zipfile.BadZipFile:
            return Response(
                {'error': 'Corrupted ZIP archive'},
                status=status.HTTP_400_BAD_REQUEST
            )
        except Exception as e:
            return Response(
                {'error': f'Processing failed: {str(e)}'},
                status=status.HTTP_500_INTERNAL_SERVER_ERROR
            )
        finally:
            shutil.rmtree(tmp_dir, ignore_errors=True)

    def _extract_archive(self, zip_path):
        """Extract ZIP contents to the upload directory.
        Filters out directories and hidden files.
        """
        extracted = []
        dest_dir = os.path.join(EXTRACT_BASE, 'incoming')
        os.makedirs(dest_dir, exist_ok=True)

        with zipfile.ZipFile(zip_path, 'r') as zf:
            for member in zf.infolist():
                # Skip directories
                if member.is_dir():
                    continue
                # Skip hidden files (macOS artifacts etc)
                basename = os.path.basename(member.filename)
                if basename.startswith('.'):
                    continue
                # Skip files larger than 10MB individually
                if member.file_size > 10 * 1024 * 1024:
                    continue

                # Extract file - uses member.filename as relative path
                target_path = os.path.join(dest_dir, member.filename)
                os.makedirs(os.path.dirname(target_path), exist_ok=True)

                with zf.open(member) as source:
                    with open(target_path, 'wb') as target:
                        shutil.copyfileobj(source, target)

                extracted.append(member.filename)

        return extracted


class DocumentListView(APIView):
    """List extracted documents available for processing."""

    def get(self, request, format=None):
        dest_dir = os.path.join(EXTRACT_BASE, 'incoming')
        if not os.path.exists(dest_dir):
            return Response({'files': []}, status=status.HTTP_200_OK)

        files = []
        for root, dirs, filenames in os.walk(dest_dir):
            for fname in filenames:
                rel_path = os.path.relpath(
                    os.path.join(root, fname), dest_dir
                )
                files.append(rel_path)

        return Response({'files': files}, status=status.HTTP_200_OK)
